import json, time
from http.server import BaseHTTPRequestHandler, HTTPServer

NOW = int(time.time()*1000)
BOOKABLES = [{"id":"b1","title":"Room-A","imgUrl":None},
             {"id":"b2","title":"Room-B","imgUrl":None}]
def bookings():
    return [
        {"timeBegin": NOW+3600_000, "timeEnd": NOW+7200_000, "bookableItems":[{"bookableId":"b1"}]},
        {"timeBegin": NOW-1800_000, "timeEnd": NOW+1800_000, "bookableItems":[{"bookableId":"b2"}]},
    ]
class H(BaseHTTPRequestHandler):
    def _send(self, code, obj):
        body=json.dumps(obj).encode()
        self.send_response(code); self.send_header("Content-Type","application/json")
        self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
    def do_POST(self):
        ln=int(self.headers.get("Content-Length",0)); self.rfile.read(ln)
        if self.path.endswith("/auth/signin"): return self._send(200,{"accessToken":"tok","refreshToken":"ref"})
        if self.path.endswith("/auth/refresh"): return self._send(200,{"accessToken":"tok2","refreshToken":"ref2"})
        self._send(404,{})
    def do_GET(self):
        if self.path.endswith("/bookables"): return self._send(200,BOOKABLES)
        if self.path.endswith("/bookings"): return self._send(200,bookings())
        self._send(404,{})
    def log_message(self,*a): pass
HTTPServer(("0.0.0.0",8002),H).serve_forever()
EOF
